module fruit_slicer (\n    input clk,\n    input rst_n,\n    input start,\n    input [5:0] n,\n    input [31:0] x [0:7],\n    input [31:0] y [0:7],\n    output reg [7:0] max_count,\n    output reg done\n);\n    // States\n    localparam [2:0] IDLE = 3\'b000;\n    localparam [2:0] COMPUTE_PROJECTIONS = 3\'b001;\n    localparam [2:0] SORT_EVENTS = 3\'b010;\n    localparam [2:0] SWEEP = 3\'b011;\n    localparam [2:0] UPDATE_MAX = 3\'b100;\n    localparam [2:0] NEXT_ANGLE = 3\'b101;\n    localparam [2:0] DONE_STATE = 3\'b110;\n    \n    // Constants\n    localparam [4:0] ANGLE_STEPS = 5\'d16;\n    localparam [31:0] RADIUS_SCALED = 32\'h00010000; // 1.0 in Q16.16\n    \n    reg [2:0] state, next_state;\n    reg [4:0] angle_index;\n    reg [4:0] circle_index;\n    reg [31:0] cos_val, sin_val;\n    reg [63:0] projection;\n    reg [63:0] events [0:15];\n    reg [4:0] event_count;\n    reg [7:0] current_max;\n    reg [7:0] overlap_count;\n    \n    // Sorting registers\n    reg [4:0] sort_i;\n    reg [4:0] sort_j;\n    reg sort_swapped;\n    \n    // Precomputed cos/sin in Q16.16 format\n    wire [31:0] cos_table [0:15];\n    wire [31:0] sin_table [0:15];\n    assign cos_table[0] = 32\'h00010000; // cos(0)\n    assign sin_table[0] = 32\'h00000000; // sin(0)\n    assign cos_table[1] = 32\'h0000EC83; // cos(π/32)\n    assign sin_table[1] = 32\'h00003240; // sin(π/32)\n    assign cos_table[2] = 32\'h0000B504; // cos(π/16)\n    assign sin_table[2] = 32\'h000061F7; // sin(π/16)\n    assign cos_table[3] = 32\'h00007168; // cos(3π/32)\n    assign sin_table[3] = 32\'h00008D3E; // sin(3π/32)\n    assign cos_table[4] = 32\'h00000000; // cos(π/8)\n    assign sin_table[4] = 32\'h0000A000; // sin(π/8) scaled\n    assign cos_table[5] = 32\'h00008D3E; // cos(5π/32)\n    assign sin_table[5] = 32\'h00007168; // sin(5π/32)\n    assign cos_table[6] = 32\'h000061F7; // cos(3π/16)\n    assign sin_table[6] = 32\'h0000B504; // sin(3π/16)\n    assign cos_table[7] = 32\'h00003240; // cos(7π/32)\n    assign sin_table[7] = 32\'h0000EC83; // sin(7π/32)\n    assign cos_table[8] = 32\'h00000000; // cos(π/4)\n    assign sin_table[8] = 32\'h00010000; // sin(π/4) approx\n    assign cos_table[9] = 32\'h00008D3E; // ... (values continued for all 16)\n    assign sin_table[9] = 32\'h00007168;\n    assign cos_table[10] = 32\'h000061F7;\n    assign sin_table[10] = 32\'h0000B504;\n    assign cos_table[11] = 32\'h00003240;\n    assign sin_table[11] = 32\'h0000EC83;\n    assign cos_table[12] = 32\'h00000000;\n    assign sin_table[12] = 32\'h0000A000;\n    assign cos_table[13] = 32\'h00007168;\n    assign sin_table[13] = 32\'h00008D3E;\n    assign cos_table[14] = 32\'h0000B504;\n    assign sin_table[14] = 32\'h000061F7;\n    assign cos_table[15] = 32\'h0000EC83;\n    assign sin_table[15] = 32\'h00003240;\n    \n    reg [4:0] i; // For loop indices in reset\n    reg [63:0] temp_event; // Swap temporary storage\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1\'b0;\n            max_count <= 8\'d0;\n            angle_index <= 5\'d0;\n            circle_index <= 5\'d0;\n            event_count <= 5\'d0;\n            current_max <= 8\'d0;\n            overlap_count <= 8\'d0;\n            cos_val <= 32\'d0;\n            sin_val <= 32\'d0;\n            projection <= 64\'d0;\n            for (i = 0; i < 16; i = i + 1) begin\n                events[i] <= 64\'d0;\n            end\n            sort_i <= 5\'d0;\n            sort_j <= 5\'d0;\n            sort_swapped <= 1\'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1\'b0;\n                    angle_index <= 5\'d0;\n                    current_max <= 8\'d0;\n                    max_count <= max_count;\n                    if (start && (n > 0) && (n <= 8)) begin\n                        state <= COMPUTE_PROJECTIONS;\n                        circle_index <= 5\'d0;\n                    end\n                end\n                \n                COMPUTE_PROJECTIONS: begin\n                    if (circle_index < n) begin\n                        cos_val <= cos_table[angle_index];\n                        sin_val <= sin_table[angle_index];\n                        // projection = x*cos + y*sin (Q16.16 arithmetic)\n                        projection <= ($signed(x[circle_index]) * $signed(cos_table[angle_index])) + \n                                      ($signed(y[circle_index]) * $signed(sin_table[angle_index]));\n                        events[2*circle_index] <= {32\'h00000001, projection - RADIUS_SCALED};\n                        events[2*circle_index +1] <= {32\'hFFFFFFFF, projection + RADIUS_SCALED};\n                        circle_index <= circle_index + 5\'d1;\n                    end else begin\n                        event_count <= n << 1;\n                        state <= SORT_EVENTS;\n                        circle_index <= 5\'d0;\n                        sort_i <= 5\'d0;\n                        sort_j <= 5\'d0;\n                        sort_swapped <= 1\'b0;\n                    end\n                end\n                \n                SORT_EVENTS: begin\n                    if (sort_i < event_count -5\'d1) begin\n                        if (sort_j < event_count - sort_i -5\'d1) begin\n                            // Compare lower 32 bits (projection value)\n                            if (events[sort_j][31:0] > events[sort_j+1][31:0]) begin\n                                temp_event = events[sort_j];\n                                events[sort_j] <= events[sort_j+1];\n                                events[sort_j+1] <= temp_event;\n                                sort_swapped <= 1\'b1;\n                            end\n                            sort_j <= sort_j +5\'d1;\n                        end else begin\n                            if (!sort_swapped) begin\n                                sort_i <= event_count; // Early termination\n                            end else begin\n                                sort_i <= sort_i +5\'d1;\n                            end\n                            sort_j <= 5\'d0;\n                            sort_swapped <= 1\'b0;\n                        end\n                    end else begin\n                        state <= SWEEP;\n                        circle_index <= 5\'d0;\n                        overlap_count <= 8\'d0;\n                    end\n                end\n                \n                SWEEP: begin\n                    if (circle_index < event_count) begin\n                        // Update overlap count based on event type (upper 32 bits)\n                        if (events[circle_index][63:32] == 32\'h00000001) begin\n                            overlap_count <= overlap_count + 8\'d1;\n                        end else begin\n                            overlap_count <= overlap_count - 8\'d1;\n                        end\n                        \n                        // Update current maximum if needed\n                        if (overlap_count > current_max) begin\n                            current_max <= overlap_count;\n                        end\n                        circle_index <= circle_index + 5\'d1;\n                    end else begin\n                        // Finished sweeping this angle\n                        state <= UPDATE_MAX;\n                    end\n                end\n                \n                UPDATE_MAX: begin\n                    if (current_max > max_count) begin\n                        max_count <= current_max;\n                    end\n                    state <= NEXT_ANGLE;\n                end\n                \n                NEXT_ANGLE: begin\n                    if (angle_index < ANGLE_STEPS -5\'d1) begin\n                        angle_index <= angle_index +5\'d1;\n                        circle_index <=5\'d0;\n                        state <= COMPUTE_PROJECTIONS;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1\'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule